import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

export type OmnichannelWhatsAppStatus = "pending" | "sent" | "delivered" | "failed" | "skipped";

/** Meta outbound status rank (mirrors whatsapp-webhook metaDeliveryRank). */
export function omnichannelDeliveryRank(status: string): number | null {
  const s = status.trim().toLowerCase();
  if (s === "read") return 4;
  if (s === "delivered") return 3;
  if (s === "sent") return 2;
  if (s === "failed") return -1;
  return null;
}

export function mapMetaStatusToOmnichannelStatus(
  metaStatus: string,
): OmnichannelWhatsAppStatus | null {
  const s = metaStatus.trim().toLowerCase();
  if (s === "failed") return "failed";
  if (s === "delivered" || s === "read") return "delivered";
  if (s === "sent") return "sent";
  return null;
}

export function shouldUpgradeOmnichannelStatus(
  current: string | null | undefined,
  incoming: OmnichannelWhatsAppStatus,
): boolean {
  if (incoming === "failed") return true;

  const cur = String(current ?? "").trim().toLowerCase();
  if (cur === "skipped") return false;
  if (cur === "failed") return false;

  const incRank = omnichannelDeliveryRank(incoming);
  if (incRank === null || incRank === -1) return false;

  const curRank = omnichannelDeliveryRank(cur);
  if (curRank === null || curRank === -1) return true;
  return incRank >= curRank;
}

export function buildMetaDeliverySkipReason(statusPayload: Record<string, unknown>): string {
  const errors = statusPayload.errors;
  const firstErr =
    Array.isArray(errors) && errors.length > 0 && errors[0] && typeof errors[0] === "object"
      ? (errors[0] as Record<string, unknown>)
      : null;

  const code = firstErr?.code != null ? String(firstErr.code).trim() : "";
  const message = String(
    firstErr?.message ?? firstErr?.title ?? statusPayload.status ?? "delivery_failed",
  ).trim();

  const codePart = code ? `#${code}:` : "";
  return `meta_delivery:${codePart}${message}`.slice(0, 500);
}

async function patchLeadSubmissions(
  admin: SupabaseClient,
  waMessageId: string,
  incoming: OmnichannelWhatsAppStatus,
  skipReason: string | null,
): Promise<number> {
  const { data: rows, error: fetchErr } = await admin
    .from("lead_submissions")
    .select("id, organization_id, whatsapp_status")
    .eq("whatsapp_message_id", waMessageId);

  if (fetchErr) {
    console.error("syncOmnichannelWhatsAppDelivery lead_submissions fetch:", fetchErr);
    return 0;
  }

  let updated = 0;
  const now = new Date().toISOString();

  for (const row of rows ?? []) {
    const current = row.whatsapp_status as string | null;
    if (!shouldUpgradeOmnichannelStatus(current, incoming)) continue;

    const patch: Record<string, unknown> = {
      whatsapp_status: incoming,
      updated_at: now,
    };
    if (incoming === "failed" && skipReason) {
      patch.whatsapp_skip_reason = skipReason;
    }

    const { error: updErr } = await admin
      .from("lead_submissions")
      .update(patch)
      .eq("id", row.id);

    if (updErr) {
      console.error("syncOmnichannelWhatsAppDelivery lead_submissions update:", updErr);
      continue;
    }

    updated += 1;
    console.log("syncOmnichannelWhatsAppDelivery: lead_submissions", {
      id: row.id,
      organization_id: row.organization_id,
      from: current,
      to: incoming,
    });
  }

  return updated;
}

async function patchSalesInvoices(
  admin: SupabaseClient,
  waMessageId: string,
  incoming: OmnichannelWhatsAppStatus,
  skipReason: string | null,
): Promise<number> {
  const { data: rows, error: fetchErr } = await admin
    .from("sales_invoices")
    .select("id, organization_id, whatsapp_status")
    .eq("whatsapp_message_id", waMessageId);

  if (fetchErr) {
    console.error("syncOmnichannelWhatsAppDelivery sales_invoices fetch:", fetchErr);
    return 0;
  }

  let updated = 0;
  const now = new Date().toISOString();

  for (const row of rows ?? []) {
    const current = row.whatsapp_status as string | null;
    if (!shouldUpgradeOmnichannelStatus(current, incoming)) continue;

    const patch: Record<string, unknown> = {
      whatsapp_status: incoming,
      updated_at: now,
    };
    if (incoming === "failed" && skipReason) {
      patch.whatsapp_skip_reason = skipReason;
    }

    const { error: updErr } = await admin
      .from("sales_invoices")
      .update(patch)
      .eq("id", row.id);

    if (updErr) {
      console.error("syncOmnichannelWhatsAppDelivery sales_invoices update:", updErr);
      continue;
    }

    updated += 1;
    console.log("syncOmnichannelWhatsAppDelivery: sales_invoices", {
      id: row.id,
      organization_id: row.organization_id,
      from: current,
      to: incoming,
    });
  }

  return updated;
}

/** Propagate Meta delivery webhook status to lead_submissions + sales_invoices by wamid. */
export async function syncOmnichannelWhatsAppDelivery(
  admin: SupabaseClient,
  args: {
    waMessageId: string;
    metaStatus: string;
    statusPayload: Record<string, unknown>;
    statusTimestampIso: string;
  },
): Promise<void> {
  const waMessageId = args.waMessageId.trim();
  if (!waMessageId) return;

  const incoming = mapMetaStatusToOmnichannelStatus(args.metaStatus);
  if (!incoming) return;

  // sent from webhook is redundant when API already set sent; still allow if row is pending.
  if (incoming === "sent") {
    // Only upgrade pending → sent (invoice rows start as pending).
    await patchLeadSubmissions(admin, waMessageId, incoming, null);
    await patchSalesInvoices(admin, waMessageId, incoming, null);
    return;
  }

  const skipReason =
    incoming === "failed" ? buildMetaDeliverySkipReason(args.statusPayload) : null;

  await Promise.all([
    patchLeadSubmissions(admin, waMessageId, incoming, skipReason),
    patchSalesInvoices(admin, waMessageId, incoming, skipReason),
  ]);

  void args.statusTimestampIso;
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { facebookPostMediaIdCandidates } from "./facebookPostMediaId.ts";
import type { LeadMagnetPlatform } from "./types.ts";
import { commentMatchesKeyword } from "./types.ts";

export type LeadMagnetCampaignAccountRow = {
  id?: string;
  campaign_id?: string;
  platform: LeadMagnetPlatform;
  account_id: string;
};

export type MatchedCampaign = {
  id: string;
  organization_id: string;
  name: string;
  keyword: string;
  status: string;
  comment_reply_text: string;
  follow_gate_text: string;
  follow_button_label: string;
  framework_offer_text: string;
  framework_button_label: string;
  delivery_text: string;
  delivery_button_label: string;
  delivery_fallback_text: string | null;
  delivery_url: string;
  skip_follow_gate_if_follower: boolean;
  skip_material_offer: boolean;
  contact_gate_enabled: boolean;
  contact_prompt_text: string | null;
  contact_invalid_text: string | null;
  contact_ack_text: string | null;
  whatsapp_account_id: string | null;
  whatsapp_template_name: string | null;
  whatsapp_template_language: string | null;
  whatsapp_template_params: Record<string, unknown>;
  email_subject: string | null;
  email_html_body: string | null;
  email_from_name: string | null;
  platform: LeadMagnetPlatform;
  account_id: string;
  posts: Array<{ media_id: string; platform: LeadMagnetPlatform }>;
};

type CampaignAccountRow = {
  platform: LeadMagnetPlatform;
  account_id: string;
};

type CampaignFromPostJoin = {
  id: string;
  organization_id: string;
  name: string;
  keyword: string;
  status: string;
  comment_reply_text: string;
  follow_gate_text: string;
  follow_button_label: string;
  framework_offer_text: string;
  framework_button_label: string;
  delivery_text: string;
  delivery_button_label: string;
  delivery_fallback_text: string | null;
  delivery_url: string;
  skip_follow_gate_if_follower: boolean;
  skip_material_offer: boolean;
  contact_gate_enabled: boolean;
  contact_prompt_text: string | null;
  contact_invalid_text: string | null;
  contact_ack_text: string | null;
  whatsapp_account_id: string | null;
  whatsapp_template_name: string | null;
  whatsapp_template_language: string | null;
  whatsapp_template_params: Record<string, unknown>;
  email_subject: string | null;
  email_html_body: string | null;
  email_from_name: string | null;
  lead_magnet_campaign_accounts: CampaignAccountRow | CampaignAccountRow[] | null;
};

function mapMatchedCampaign(
  campaign: CampaignFromPostJoin,
  args: {
    platform: LeadMagnetPlatform;
    accountId: string;
    mediaId: string;
  },
): MatchedCampaign | null {
  const accountsRaw = campaign.lead_magnet_campaign_accounts;
  const accounts = Array.isArray(accountsRaw)
    ? accountsRaw
    : accountsRaw
    ? [accountsRaw]
    : [];
  const binding = accounts.find(
    (row) => row.platform === args.platform && String(row.account_id) === args.accountId,
  );
  if (!binding) return null;

  return {
    id: String(campaign.id),
    organization_id: String(campaign.organization_id),
    name: String(campaign.name),
    keyword: String(campaign.keyword),
    status: String(campaign.status),
    comment_reply_text: String(campaign.comment_reply_text),
    follow_gate_text: String(campaign.follow_gate_text),
    follow_button_label: String(campaign.follow_button_label),
    framework_offer_text: String(campaign.framework_offer_text),
    framework_button_label: String(campaign.framework_button_label),
    delivery_text: String(campaign.delivery_text),
    delivery_button_label: String(campaign.delivery_button_label),
    delivery_fallback_text: campaign.delivery_fallback_text != null
      ? String(campaign.delivery_fallback_text)
      : null,
    delivery_url: String(campaign.delivery_url),
    skip_follow_gate_if_follower: Boolean(campaign.skip_follow_gate_if_follower),
    skip_material_offer: Boolean(campaign.skip_material_offer),
    contact_gate_enabled: Boolean(campaign.contact_gate_enabled),
    contact_prompt_text: campaign.contact_prompt_text ?? null,
    contact_invalid_text: campaign.contact_invalid_text ?? null,
    contact_ack_text: campaign.contact_ack_text ?? null,
    whatsapp_account_id: campaign.whatsapp_account_id ?? null,
    whatsapp_template_name: campaign.whatsapp_template_name ?? null,
    whatsapp_template_language: campaign.whatsapp_template_language ?? null,
    whatsapp_template_params: (campaign.whatsapp_template_params ?? {}) as Record<string, unknown>,
    email_subject: campaign.email_subject ?? null,
    email_html_body: campaign.email_html_body ?? null,
    email_from_name: campaign.email_from_name ?? null,
    platform: args.platform,
    account_id: String(binding.account_id),
    posts: [{ media_id: args.mediaId, platform: args.platform }],
  };
}

export async function findMatchingLeadMagnetCampaign(
  admin: SupabaseClient,
  args: {
    organizationId: string;
    platform: LeadMagnetPlatform;
    accountId: string;
    mediaId: string;
    commentText: string;
  },
): Promise<MatchedCampaign | null> {
  const mediaIdCandidates = args.platform === "facebook"
    ? facebookPostMediaIdCandidates(args.mediaId, args.accountId)
    : [args.mediaId.trim()].filter(Boolean);

  const { data: rows, error } = await admin
    .from("lead_magnet_campaign_posts")
    .select(`
      media_id,
      platform,
      lead_magnet_campaigns!inner (
        id,
        organization_id,
        name,
        keyword,
        status,
        comment_reply_text,
        follow_gate_text,
        follow_button_label,
        framework_offer_text,
        framework_button_label,
        delivery_text,
        delivery_button_label,
        delivery_fallback_text,
        delivery_url,
        skip_follow_gate_if_follower,
        skip_material_offer,
        contact_gate_enabled,
        contact_prompt_text,
        contact_invalid_text,
        contact_ack_text,
        whatsapp_account_id,
        whatsapp_template_name,
        whatsapp_template_language,
        whatsapp_template_params,
        email_subject,
        email_html_body,
        email_from_name,
        lead_magnet_campaign_accounts (platform, account_id)
      )
    `)
    .eq("platform", args.platform)
    .in("media_id", mediaIdCandidates.length ? mediaIdCandidates : [args.mediaId]);

  if (error) {
    console.error("[lead-magnet] campaign match query failed:", error.message);
    return null;
  }
  if (!rows?.length) return null;

  for (const row of rows as Array<{
    media_id: string;
    platform: LeadMagnetPlatform;
    lead_magnet_campaigns: CampaignFromPostJoin | CampaignFromPostJoin[] | null;
  }>) {
    const campaignRaw = row.lead_magnet_campaigns;
    const campaign = Array.isArray(campaignRaw) ? campaignRaw[0] : campaignRaw;
    if (!campaign) continue;
    if (String(campaign.organization_id) !== args.organizationId) continue;
    if (String(campaign.status) !== "active") continue;
    if (!commentMatchesKeyword(args.commentText, String(campaign.keyword ?? ""))) continue;

    const matched = mapMatchedCampaign(campaign, {
      platform: args.platform,
      accountId: args.accountId,
      mediaId: String(row.media_id),
    });
    if (matched) return matched;
  }

  return null;
}

export async function enrollmentExists(
  admin: SupabaseClient,
  campaignId: string,
  participantScopedId: string,
): Promise<boolean> {
  const { data } = await admin
    .from("lead_magnet_enrollments")
    .select("id")
    .eq("campaign_id", campaignId)
    .eq("participant_scoped_id", participantScopedId)
    .maybeSingle();
  return Boolean(data?.id);
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { replyMetaComment } from "../metaContentApi.ts";
import { findMatchingLeadMagnetCampaign } from "./campaignMatcher.ts";
import { createLeadMagnetLead } from "./createLeadMagnetLead.ts";
import { fetchCommentText } from "./fetchParticipantProfile.ts";
import { logLeadMagnetFunnelEvent, updateEnrollmentStatus } from "./funnelAnalytics.ts";
import { runFollowCheckAndDmFlow, isPostContactGateEnrollmentStatus } from "./followGateRuntime.ts";
import { deferLeadMagnetWork } from "./webhookBridge.ts";
import type { LeadMagnetCommentTriggerInput, LeadMagnetEnrollmentRow } from "./types.ts";

function buildPublicCommentReply(text: string, username: string | null): string {
  const handle = (username ?? "").trim().replace(/^@/, "");
  if (!handle) return text;
  const mention = `@${handle}`;
  if (text.includes(mention)) return text;
  return `${mention} ${text}`;
}

async function sendPublicCommentReply(
  admin: SupabaseClient,
  args: {
    platform: LeadMagnetCommentTriggerInput["platform"];
    commentId: string;
    accessToken: string;
    campaign: { id: string; comment_reply_text: string };
    organizationId: string;
    enrollmentId: string;
    authorUsername: string | null;
    retry?: boolean;
  },
): Promise<boolean> {
  const advancedStatuses = new Set([
    "follow_gate_sent",
    "follow_checked",
    "follow_validated",
    "framework_offered",
    "material_offer_skipped",
    "awaiting_contact",
    "contact_collected",
    "delivered",
    "delivered_whatsapp",
    "delivered_email",
    "delivered_instagram",
  ]);

  try {
    const replyText = buildPublicCommentReply(args.campaign.comment_reply_text, args.authorUsername);
    const replyResult = await replyMetaComment(args.platform, args.commentId, replyText, args.accessToken);
    deferLeadMagnetWork((async () => {
      const { data: current } = await admin
        .from("lead_magnet_enrollments")
        .select("status")
        .eq("id", args.enrollmentId)
        .maybeSingle();
      const currentStatus = (current?.status as string | undefined) ?? "comment_replied";
      const nextStatus = advancedStatuses.has(currentStatus) ? currentStatus : "comment_replied";

      await updateEnrollmentStatus(admin, args.enrollmentId, nextStatus, {
        comment_reply_id: replyResult.id,
      });
      await logLeadMagnetFunnelEvent(admin, {
        enrollmentId: args.enrollmentId,
        campaignId: args.campaign.id,
        organizationId: args.organizationId,
        eventType: "comment_reply_sent",
        metadata: {
          reply_id: replyResult.id,
          comment_id: args.commentId,
          ...(args.retry ? { retry: true } : {}),
        },
      });
      await logLeadMagnetFunnelEvent(admin, {
        enrollmentId: args.enrollmentId,
        campaignId: args.campaign.id,
        organizationId: args.organizationId,
        eventType: "comment_replied",
        metadata: args.retry ? { retry: true } : undefined,
      });
    })());
    return true;
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error("[lead-magnet] comment reply failed:", msg);
    deferLeadMagnetWork(updateEnrollmentStatus(admin, args.enrollmentId, "comment_replied", {
      last_error: `comment_reply: ${msg}`,
    }));
    return false;
  }
}

function scheduleFollowCheckAndDmFlow(
  admin: SupabaseClient,
  args: {
    enrollment: LeadMagnetEnrollmentRow;
    campaign: Parameters<typeof runFollowCheckAndDmFlow>[1]["campaign"];
    accessToken: string;
    pageId: string;
  },
): void {
  deferLeadMagnetWork(
    runFollowCheckAndDmFlow(admin, args).catch((err) => {
      console.error("[lead-magnet] deferred DM flow failed:", err);
    }),
  );
}

function isFacebookSessionExpiredError(lastError: string | null | undefined): boolean {
  const err = (lastError ?? "").toLowerCase();
  return err.includes("outside the allowed window") || err.includes("(#10)");
}

function canRestartFacebookDmFlow(existing: Record<string, unknown>): boolean {
  const status = String(existing.status ?? "");
  if (status === "follow_gate_sent") return true;
  if (!isFacebookSessionExpiredError(existing.last_error as string | null)) return false;
  return ["follow_validated", "framework_offered", "failed"].includes(status);
}

export async function handleLeadMagnetCommentTrigger(
  admin: SupabaseClient,
  input: LeadMagnetCommentTriggerInput,
): Promise<boolean> {
  let commentText = input.commentText.trim();
  let authorUsername = input.authorUsername;

  if (!commentText) {
    const fetched = await fetchCommentText(input.commentId, input.accessToken);
    commentText = (fetched.text ?? "").trim();
    if (!authorUsername && fetched.username) authorUsername = fetched.username;
  }

  if (!commentText) {
    console.log("[lead-magnet] skip comment without text", input.commentId);
    return false;
  }

  const campaign = await findMatchingLeadMagnetCampaign(admin, {
    organizationId: input.organizationId,
    platform: input.platform,
    accountId: input.accountId,
    mediaId: input.mediaId,
    commentText,
  });

  if (!campaign) return false;

  const enrollmentId = crypto.randomUUID();
  const now = new Date().toISOString();

  const { error: enrollErr } = await admin.from("lead_magnet_enrollments").insert({
    id: enrollmentId,
    organization_id: input.organizationId,
    campaign_id: campaign.id,
    platform: input.platform,
    participant_scoped_id: input.authorScopedId,
    participant_username: authorUsername,
    comment_id: input.commentId,
    media_id: input.mediaId,
    status: "comment_matched",
    created_at: now,
    updated_at: now,
  });

  if (enrollErr) {
    if (enrollErr.code === "23505") {
      const { data: existing } = await admin
        .from("lead_magnet_enrollments")
        .select("*")
        .eq("campaign_id", campaign.id)
        .eq("participant_scoped_id", input.authorScopedId)
        .maybeSingle();

      const canRetryFailedFirstContact = existing
        && !existing.private_reply_message_id
        && (existing.status === "failed" || existing.status === "comment_replied")
        && (input.platform === "instagram" || input.platform === "facebook");

      const canResendFacebookFollowGate = existing
        && input.platform === "facebook"
        && canRestartFacebookDmFlow(existing);

      if (canResendFacebookFollowGate && existing) {
        console.log("[lead-magnet] restart FB DM flow after new comment", existing.id, input.commentId, existing.status);
        await admin.from("lead_magnet_enrollments").update({
          comment_id: input.commentId,
          media_id: input.mediaId,
          participant_username: authorUsername ?? existing.participant_username,
          status: "comment_matched",
          private_reply_message_id: null,
          private_reply_sent_at: null,
          first_dm_method: null,
          follow_confirm_attempts: 0,
          last_error: null,
          updated_at: new Date().toISOString(),
        }).eq("id", existing.id);

        const enrollmentRow: LeadMagnetEnrollmentRow = {
          id: existing.id as string,
          organization_id: existing.organization_id as string,
          campaign_id: existing.campaign_id as string,
          platform: existing.platform as LeadMagnetEnrollmentRow["platform"],
          participant_scoped_id: existing.participant_scoped_id as string,
          participant_username: (authorUsername ?? existing.participant_username) as string | null,
          comment_id: input.commentId,
          media_id: input.mediaId,
          conversation_id: (existing.conversation_id as string | null) ?? null,
          conversation_table: (existing.conversation_table as string | null) ?? null,
          lead_submission_id: (existing.lead_submission_id as string | null) ?? null,
          lead_id: (existing.lead_id as string | null) ?? null,
          status: "comment_matched",
          paused_reason: (existing.paused_reason as string | null) ?? null,
          is_follower_at_start: null,
          last_error: null,
        };

        await sendPublicCommentReply(admin, {
          platform: input.platform,
          commentId: input.commentId,
          accessToken: input.accessToken,
          campaign,
          organizationId: input.organizationId,
          enrollmentId: existing.id as string,
          authorUsername,
          retry: true,
        });

        scheduleFollowCheckAndDmFlow(admin, {
          enrollment: enrollmentRow,
          campaign,
          accessToken: input.accessToken,
          pageId: input.pageId,
        });
        return true;
      }

      if (canRetryFailedFirstContact && existing) {
        console.log("[lead-magnet] retry failed enrollment with new comment", existing.id, input.commentId);
        await admin.from("lead_magnet_enrollments").update({
          comment_id: input.commentId,
          media_id: input.mediaId,
          participant_username: authorUsername ?? existing.participant_username,
          status: "comment_matched",
          last_error: null,
          updated_at: new Date().toISOString(),
        }).eq("id", existing.id);

        const enrollmentRow: LeadMagnetEnrollmentRow = {
          id: existing.id as string,
          organization_id: existing.organization_id as string,
          campaign_id: existing.campaign_id as string,
          platform: existing.platform as LeadMagnetEnrollmentRow["platform"],
          participant_scoped_id: existing.participant_scoped_id as string,
          participant_username: (authorUsername ?? existing.participant_username) as string | null,
          comment_id: input.commentId,
          media_id: input.mediaId,
          conversation_id: null,
          conversation_table: null,
          lead_submission_id: (existing.lead_submission_id as string | null) ?? null,
          lead_id: (existing.lead_id as string | null) ?? null,
          status: "comment_matched",
          paused_reason: (existing.paused_reason as string | null) ?? null,
          is_follower_at_start: null,
          last_error: null,
        };

        await sendPublicCommentReply(admin, {
          platform: input.platform,
          commentId: input.commentId,
          accessToken: input.accessToken,
          campaign,
          organizationId: input.organizationId,
          enrollmentId: existing.id as string,
          authorUsername,
          retry: true,
        });

        scheduleFollowCheckAndDmFlow(admin, {
          enrollment: enrollmentRow,
          campaign,
          accessToken: input.accessToken,
          pageId: input.pageId,
        });
        return true;
      }

      console.log("[lead-magnet] dedup enrollment", campaign.id, input.authorScopedId);
      await sendPublicCommentReply(admin, {
        platform: input.platform,
        commentId: input.commentId,
        accessToken: input.accessToken,
        campaign,
        organizationId: input.organizationId,
        enrollmentId: existing!.id as string,
        authorUsername,
      });

      if (existing && !existing.private_reply_message_id) {
        const { data: freshExisting } = await admin
          .from("lead_magnet_enrollments")
          .select("*")
          .eq("id", existing.id)
          .maybeSingle();
        const enrollmentForFlow = (freshExisting ?? existing) as Record<string, unknown>;
        const flowStatus = String(enrollmentForFlow.status ?? "");

        await admin.from("lead_magnet_enrollments").update({
          comment_id: input.commentId,
          media_id: input.mediaId,
          participant_username: authorUsername ?? existing.participant_username,
          last_error: null,
          updated_at: new Date().toISOString(),
        }).eq("id", existing.id);

        if (!isPostContactGateEnrollmentStatus(flowStatus)) {
          const enrollmentRow: LeadMagnetEnrollmentRow = {
            id: existing.id as string,
            organization_id: existing.organization_id as string,
            campaign_id: existing.campaign_id as string,
            platform: existing.platform as LeadMagnetEnrollmentRow["platform"],
            participant_scoped_id: existing.participant_scoped_id as string,
            participant_username: (authorUsername ?? existing.participant_username) as string | null,
            comment_id: input.commentId,
            media_id: input.mediaId,
            conversation_id: (enrollmentForFlow.conversation_id as string | null) ?? null,
            conversation_table: (enrollmentForFlow.conversation_table as string | null) ?? null,
            lead_submission_id: (enrollmentForFlow.lead_submission_id as string | null) ?? null,
            lead_id: (enrollmentForFlow.lead_id as string | null) ?? null,
            status: flowStatus as LeadMagnetEnrollmentRow["status"],
            paused_reason: (enrollmentForFlow.paused_reason as string | null) ?? null,
            is_follower_at_start: (enrollmentForFlow.is_follower_at_start as boolean | null) ?? null,
            last_error: null,
            private_reply_message_id: null,
          };

          scheduleFollowCheckAndDmFlow(admin, {
            enrollment: enrollmentRow,
            campaign,
            accessToken: input.accessToken,
            pageId: input.pageId,
          });
        }
      }
      return true;
    }
    console.error("[lead-magnet] enrollment insert failed:", enrollErr.message);
    return false;
  }

  deferLeadMagnetWork(
    logLeadMagnetFunnelEvent(admin, {
      enrollmentId,
      campaignId: campaign.id,
      organizationId: input.organizationId,
      eventType: "comment_matched",
      metadata: { comment_id: input.commentId, media_id: input.mediaId },
    }),
  );

  const enrollmentRow: LeadMagnetEnrollmentRow = {
    id: enrollmentId,
    organization_id: input.organizationId,
    campaign_id: campaign.id,
    platform: input.platform,
    participant_scoped_id: input.authorScopedId,
    participant_username: authorUsername,
    comment_id: input.commentId,
    media_id: input.mediaId,
    conversation_id: null,
    conversation_table: null,
    lead_submission_id: null,
    lead_id: null,
    status: "comment_matched",
    paused_reason: null,
    is_follower_at_start: null,
    last_error: null,
  };

  // 1) Public comment reply first (sync) — user-visible; target <3s from webhook.
  await sendPublicCommentReply(admin, {
    platform: input.platform,
    commentId: input.commentId,
    accessToken: input.accessToken,
    campaign,
    organizationId: input.organizationId,
    enrollmentId,
    authorUsername,
  });

  // 2) Follow check + DM in background (profile fetch + Messenger API).
  scheduleFollowCheckAndDmFlow(admin, {
    enrollment: enrollmentRow,
    campaign,
    accessToken: input.accessToken,
    pageId: input.pageId,
  });

  deferLeadMagnetWork(createLeadMagnetLead(admin, {
    organizationId: input.organizationId,
    campaign,
    enrollmentId,
    participantUsername: authorUsername,
    participantScopedId: input.authorScopedId,
    platform: input.platform,
    mediaId: input.mediaId,
  }));

  return true;
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { deliverViaInstagramDm } from "../delivery/deliverViaInstagramDm.ts";
import { logLeadMagnetFunnelEvent } from "../funnelAnalytics.ts";
import type { LeadMagnetCampaignRow, LeadMagnetEnrollmentRow } from "../types.ts";
import { getParticipantProfile } from "./participantProfile.ts";
import { isContactGateEnabled, resolveFlowBranch } from "./skipMatrix.ts";
import { sendContactPrompt } from "./contactGatePrompt.ts";

export async function advanceAfterFollowValidated(
  admin: SupabaseClient,
  args: {
    enrollment: LeadMagnetEnrollmentRow;
    campaign: LeadMagnetCampaignRow;
    accessToken: string;
    pageId: string;
    isFollower?: boolean;
  },
): Promise<boolean> {
  if (!isContactGateEnabled(args.campaign)) {
    const { sendMaterialOfferOrDelivery } = await import("../followGateRuntime.ts");
    return sendMaterialOfferOrDelivery(admin, args);
  }

  await logLeadMagnetFunnelEvent(admin, {
    enrollmentId: args.enrollment.id,
    campaignId: args.campaign.id,
    organizationId: args.enrollment.organization_id,
    eventType: "material_offer_skipped",
    metadata: { reason: "contact_gate_enabled" },
  });

  const profile = await getParticipantProfile(admin, {
    organizationId: args.enrollment.organization_id,
    platform: args.enrollment.platform,
    participantScopedId: args.enrollment.participant_scoped_id,
  });

  const branch = resolveFlowBranch({
    campaign: args.campaign,
    profile: profile ?? { phone_number: null, email: null },
    isFollower: args.isFollower ?? true,
  });

  if (branch.branch === "deliver_instagram") {
    return deliverViaInstagramDm(admin, args);
  }
  if (branch.branch === "needs_contact") {
    return sendContactPrompt(admin, { ...args, ask: branch.ask });
  }

  const { sendMaterialOfferOrDelivery } = await import("../followGateRuntime.ts");
  return sendMaterialOfferOrDelivery(admin, args);
}

export async function advanceContactGateOnComment(
  admin: SupabaseClient,
  args: {
    enrollment: LeadMagnetEnrollmentRow;
    campaign: LeadMagnetCampaignRow;
    accessToken: string;
    pageId: string;
    isFollower: boolean;
  },
): Promise<boolean> {
  if (!isContactGateEnabled(args.campaign)) {
    return false;
  }

  const profile = await getParticipantProfile(admin, {
    organizationId: args.enrollment.organization_id,
    platform: args.enrollment.platform,
    participantScopedId: args.enrollment.participant_scoped_id,
  });

  const branch = resolveFlowBranch({
    campaign: args.campaign,
    profile: profile ?? { phone_number: null, email: null },
    isFollower: args.isFollower,
  });

  if (branch.branch === "deliver_instagram" && args.isFollower) {
    await logLeadMagnetFunnelEvent(admin, {
      enrollmentId: args.enrollment.id,
      campaignId: args.campaign.id,
      organizationId: args.enrollment.organization_id,
      eventType: "material_offer_skipped",
      metadata: { reason: "profile_complete_ig_delivery" },
    });
    return deliverViaInstagramDm(admin, args);
  }

  return false;
}

